mod common;

use axum::Router;
use axum::http::StatusCode;
use common::{connect_db, db_dump, register_example_manga, request, request_bytes, test_app};
use serde_json::{Value, json};

/// Generated by tests/fixtures/gen_example_aib.py (python plistlib, binary plist);
/// contents: 3 library entries (1 with an uninstalled source), 4 progress entries (1 with an
/// uninstalled source), 2 categories (both the string and object forms), 4 tracker bindings
/// (1 on an uninstalled source, 1 for an unsupported tracker) and a settings dump carrying the
/// per-manga chapter display modes that become the bindings' track modes
const AIB: &[u8] = include_bytes!("fixtures/example.aib");

const DATE_ADDED_MANGA2: i64 = 1704960000; // 2024-01-11 08:00:00 UTC
const DATE_READ_CH3: i64 = 1706781600; // 2024-02-01 10:00:00 UTC
const DATE_READ_CH7: i64 = 1706868000; // 2024-02-02 10:00:00 UTC
const DATE_READ_MANGA2: i64 = 1706954400; // 2024-02-03 10:00:00 UTC

async fn post_aib(app: &Router, query: &str) -> (StatusCode, Value) {
	post_aib_bytes(app, query, AIB.to_vec()).await
}

async fn post_aib_bytes(app: &Router, query: &str, body: Vec<u8>) -> (StatusCode, Value) {
	let (status, _, bytes) = request_bytes(
		app,
		"POST",
		&format!("/api/v1/backups/import/aidoku{query}"),
		body,
		"application/octet-stream",
	)
	.await;
	let value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
	(status, value)
}

async fn scan(app: &Router) {
	let (status, _) = request(app, "POST", "/api/v1/sources/scan", None).await;
	assert_eq!(status, StatusCode::OK);
}

/// Fetches a row from the manga's chapter list by chapter key
async fn chapter_by_key(app: &Router, manga_id: i64, key: &str) -> Value {
	let (_, chapters) = request(app, "GET", &format!("/api/v1/manga/{manga_id}/chapters"), None).await;
	chapters
		.as_array()
		.expect("chapters")
		.iter()
		.find(|c| c["key"] == key)
		.unwrap_or_else(|| panic!("chapter {key}"))
		.clone()
}

/// Library entry by title, as the import created it
async fn library_entry(app: &Router, title: &str) -> Value {
	let (_, lib) = request(app, "GET", "/api/v1/library", None).await;
	lib["entries"]
		.as_array()
		.expect("entries")
		.iter()
		.find(|e| e["title"] == title)
		.unwrap_or_else(|| panic!("library entry {title}"))
		.clone()
}

/// The manga's tracker bindings through the REST surface the web UI reads
async fn tracker_links(app: &Router, manga_id: i64) -> Vec<Value> {
	let (status, links) = request(app, "GET", &format!("/api/v1/trackers/links/{manga_id}"), None).await;
	assert_eq!(status, StatusCode::OK, "links: {links}");
	links.as_array().expect("links").clone()
}

#[tokio::test]
async fn import_aidoku_merges_with_existing_state() {
	let app = test_app().await;
	scan(&app.app).await;
	let manga_id = register_example_manga(&app.app).await;

	// preset category Evening with modified tri-state flags: the import must not overwrite an existing category's definition
	let (status, body) = request(&app.app, "POST", "/api/v1/categories", Some(json!({"name": "Evening"}))).await;
	assert_eq!(status, StatusCode::OK);
	let evening_id = body["id"].as_i64().expect("category id");
	let (status, _) = request(
		&app.app,
		"POST",
		"/api/v1/library",
		Some(json!({"mangaId": manga_id, "categoryIds": [evening_id]})),
	)
	.await;
	assert_eq!(status, StatusCode::OK);
	let (_, lib_before) = request(&app.app, "GET", "/api/v1/library", None).await;
	let added_before = lib_before["entries"][0]["inLibraryAt"].as_i64().expect("inLibraryAt");

	// ch3: existing progress has a higher page (9 > the backup's 5), so max must keep 9; the PATCH's lastReadAt is newer than the backup's
	let ch3 = chapter_by_key(&app.app, manga_id, "3").await;
	let ch3_id = ch3["id"].as_i64().expect("ch3 id");
	let (status, _) = request(
		&app.app,
		"PATCH",
		&format!("/api/v1/chapter/{ch3_id}"),
		Some(json!({"lastPageRead": 9})),
	)
	.await;
	assert_eq!(status, StatusCode::OK);
	let ch3_before = chapter_by_key(&app.app, manga_id, "3").await;

	// ch7: seed a very old last_read_at via direct SQL; the backup's dateRead is newer and must override
	let ch7 = chapter_by_key(&app.app, manga_id, "7").await;
	let ch7_id = ch7["id"].as_i64().expect("ch7 id");
	let pool = connect_db(&app.db_path).await;
	sqlx::query(
		"INSERT INTO chapter_user (chapter_id, user_id, last_page_read, is_read, is_bookmarked, last_read_at)
		 VALUES (?, 1, 0, 0, 0, 1)",
	)
	.bind(ch7_id)
	.execute(&pool)
	.await
	.expect("seed ch7 progress");
	pool.close().await;

	let (status, body) = post_aib(&app.app, "").await;
	assert_eq!(status, StatusCode::OK, "import failed: {body}");
	assert_eq!(body["dryRun"], false);
	assert_eq!(body["imported"]["library"], 2);
	assert_eq!(body["imported"]["categories"], 3);
	assert_eq!(body["imported"]["progress"], 3);
	assert_eq!(body["imported"]["trackers"], 2);
	// the 2 uninstalled-source skips plus one unsupported tracker and one tracker on an uninstalled source
	let skipped = body["skipped"].as_array().expect("skipped");
	assert_eq!(skipped.len(), 4, "skipped: {skipped:?}");
	assert!(skipped.iter().all(|s| s["section"] != "categories"));
	let library_skip = skipped
		.iter()
		.find(|s| s["section"] == "library")
		.expect("library skip");
	assert_eq!(library_skip["sourceKey"], "en.ghost-source");
	assert_eq!(library_skip["mangaKey"], "ghost-1");
	let progress_skip = skipped
		.iter()
		.find(|s| s["section"] == "progress")
		.expect("progress skip");
	assert_eq!(progress_skip["sourceKey"], "en.ghost-source");
	assert_eq!(progress_skip["mangaKey"], "ghost-1");
	assert_eq!(progress_skip["chapterKey"], "9");
	let tracker_skips: Vec<_> = skipped
		.iter()
		.filter(|s| s["section"] == "trackers")
		.collect();
	assert_eq!(tracker_skips.len(), 2, "tracker skips: {tracker_skips:?}");
	// an unsupported tracker is reported instead of guessed at...
	assert!(
		tracker_skips
			.iter()
			.any(|s| s["reason"] == "tracker not supported" && s["sourceKey"] == "en.example-source")
	);
	// ...and a tracker whose manga's source is not installed loses the source check first
	assert!(
		tracker_skips
			.iter()
			.any(|s| s["reason"] == "source not installed" && s["sourceKey"] == "en.ghost-source")
	);

	// library: manga 1 already exists, its title is not overwritten by backup metadata; manga 2 is created from backup metadata
	let (_, lib) = request(&app.app, "GET", "/api/v1/library", None).await;
	let entries = lib["entries"].as_array().expect("entries");
	assert_eq!(entries.len(), 2);
	let manga1 = entries
		.iter()
		.find(|e| e["id"] == manga_id)
		.expect("manga 1 entry");
	assert_eq!(manga1["title"], "");
	assert_eq!(manga1["inLibraryAt"], added_before);
	let manga2 = entries
		.iter()
		.find(|e| e["title"] == "Second Manga")
		.expect("manga 2 entry");
	assert_eq!(manga2["authors"], json!(["Author B"]));
	assert_eq!(manga2["inLibraryAt"], DATE_ADDED_MANGA2);
	let manga2_id = manga2["id"].as_i64().expect("manga 2 id");
	let pool = connect_db(&app.db_path).await;
	let tracking: (i64, i64) = sqlx::query_as(
		"SELECT last_modified_at,
		 (SELECT COUNT(*) FROM sync_change WHERE entity_kind = 'manga_user' AND entity_key = ?)
		 FROM manga_user WHERE manga_id = ? AND user_id = 1",
	)
	.bind(format!("{manga2_id}:1"))
	.bind(manga2_id)
	.fetch_one(&pool)
	.await
	.expect("imported tracking");
	assert!(tracking.0 >= 1_000_000_000_000);
	assert_eq!(tracking.1, 1);
	pool.close().await;

	// progress merge: max(page) / OR(read) / newer(timestamp)
	let ch3_after = chapter_by_key(&app.app, manga_id, "3").await;
	assert_eq!(ch3_after["lastPageRead"], 9);
	assert_eq!(ch3_after["isRead"], false);
	assert_eq!(ch3_after["lastReadAt"], ch3_before["lastReadAt"]);
	let ch7_after = chapter_by_key(&app.app, manga_id, "7").await;
	assert_eq!(ch7_after["isRead"], true);
	assert_eq!(ch7_after["lastReadAt"], DATE_READ_CH7);

	// manga 2 created during import: chapter rows are filled in from the backup's chapters metadata, progress persisted
	let m2_ch1 = chapter_by_key(&app.app, manga2_id, "1").await;
	assert_eq!(m2_ch1["title"], "Ch 1");
	assert_eq!(m2_ch1["lastPageRead"], 2);
	assert_eq!(m2_ch1["isRead"], false);
	assert_eq!(m2_ch1["lastReadAt"], DATE_READ_MANGA2);

	// categories: existing Evening's tri-state flags untouched; Reading/Favorites created; membership filled from library entries
	let (_, cats) = request(&app.app, "GET", "/api/v1/categories", None).await;
	let cats = cats.as_array().expect("categories");
	let evening = cats.iter().find(|c| c["name"] == "Evening").expect("Evening");
	assert!(!evening.as_object().unwrap().contains_key("includeInUpdate"));
	assert_eq!(evening["mangaCount"], 1);
	let reading = cats.iter().find(|c| c["name"] == "Reading").expect("Reading");
	assert_eq!(reading["mangaCount"], 2);
	let favorites = cats
		.iter()
		.find(|c| c["name"] == "Favorites")
		.expect("Favorites");
	assert_eq!(favorites["mangaCount"], 1);

	let before = db_dump(&app.db_path).await;
	let (status, body) = post_aib(&app.app, "").await;
	assert_eq!(status, StatusCode::OK, "identical import failed: {body}");
	// bindings already exist: the repeat import reports them as imported (kept) without changing anything
	assert_eq!(body["imported"]["trackers"], 2);
	assert_eq!(db_dump(&app.db_path).await, before);
}

/// Pinpoint assertions for the three directions max / OR / newer: changing the override semantics turns this red
#[tokio::test]
async fn import_aidoku_progress_takes_max_or_newer() {
	let app = test_app().await;
	scan(&app.app).await;
	let manga_id = register_example_manga(&app.app).await;
	let pool = connect_db(&app.db_path).await;

	// ch3 is read with a lower page and older time: backup progress=5 unread → page rises to 5, read stays, time takes the backup's
	let ch3 = chapter_by_key(&app.app, manga_id, "3").await;
	sqlx::query(
		"INSERT INTO chapter_user (chapter_id, user_id, last_page_read, is_read, is_bookmarked, last_read_at)
		 VALUES (?, 1, 3, 1, 0, 1)",
	)
	.bind(ch3["id"].as_i64().expect("ch3 id"))
	.execute(&pool)
	.await
	.expect("seed ch3");
	// ch7 has a higher page but is unread with no time: backup progress=-1 fully read → page stays 9, read set true, time takes the backup's
	let ch7 = chapter_by_key(&app.app, manga_id, "7").await;
	sqlx::query(
		"INSERT INTO chapter_user (chapter_id, user_id, last_page_read, is_read, is_bookmarked, last_read_at)
		 VALUES (?, 1, 9, 0, 0, NULL)",
	)
	.bind(ch7["id"].as_i64().expect("ch7 id"))
	.execute(&pool)
	.await
	.expect("seed ch7");
	pool.close().await;

	let (status, body) = post_aib(&app.app, "").await;
	assert_eq!(status, StatusCode::OK, "import failed: {body}");

	let ch3_after = chapter_by_key(&app.app, manga_id, "3").await;
	assert_eq!(ch3_after["lastPageRead"], 5);
	assert_eq!(ch3_after["isRead"], true);
	assert_eq!(ch3_after["lastReadAt"], DATE_READ_CH3);
	let ch7_after = chapter_by_key(&app.app, manga_id, "7").await;
	assert_eq!(ch7_after["lastPageRead"], 9);
	assert_eq!(ch7_after["isRead"], true);
	assert_eq!(ch7_after["lastReadAt"], DATE_READ_CH7);
}

#[tokio::test]
async fn import_aidoku_dry_run_reports_without_writing() {
	let app = test_app().await;
	scan(&app.app).await;
	let before = db_dump(&app.db_path).await;

	let (status, body) = post_aib(&app.app, "?dryRun=true").await;
	assert_eq!(status, StatusCode::OK, "dry-run failed: {body}");
	assert_eq!(body["dryRun"], true);
	assert_eq!(body["imported"]["library"], 2);
	assert_eq!(body["imported"]["categories"], 3);
	assert_eq!(body["imported"]["progress"], 3);
	assert_eq!(body["imported"]["trackers"], 2);
	assert_eq!(body["skipped"].as_array().expect("skipped").len(), 4);
	assert_eq!(body["categoryNames"], json!(["Evening", "Favorites", "Reading"]));
	let included = body["included"].as_array().expect("included rows");
	assert_eq!(included.len(), 7);
	assert!(included.iter().any(|entry| entry["section"] == "library" && entry["mangaTitle"] == "Second Manga"));
	assert!(included.iter().any(|entry| entry["section"] == "progress" && entry["chapterTitle"] == "Ch 3"));
	assert!(body["skipped"].as_array().unwrap().iter().any(|entry| entry["reason"] == "tracker not supported" && entry["trackerId"] == "shikimori"));
	assert_eq!(db_dump(&app.db_path).await, before);

	let (_, lib) = request(&app.app, "GET", "/api/v1/library", None).await;
	assert_eq!(lib["entries"].as_array().expect("entries").len(), 0);
	let (status, committed) = post_aib(&app.app, "").await;
	assert_eq!(status, StatusCode::OK);
	for field in ["imported", "included", "categoryNames", "skipped"] {
		assert_eq!(committed[field], body[field], "{field} differs from preview");
	}
}

#[tokio::test]
async fn import_aidoku_rejects_invalid_input() {
	let app = test_app().await;
	scan(&app.app).await;
	let before = db_dump(&app.db_path).await;

	for (label, body) in [
		("not a plist", b"garbage bytes".to_vec()),
		("json is not plist", br#"{"version":1}"#.to_vec()),
	] {
		let (status, resp) = {
			let (status, _, bytes) = request_bytes(
				&app.app,
				"POST",
				"/api/v1/backups/import/aidoku",
				body,
				"application/octet-stream",
			)
			.await;
			(status, serde_json::from_slice::<Value>(&bytes).unwrap_or(Value::Null))
		};
		assert_eq!(status, StatusCode::BAD_REQUEST, "{label}: {resp}");
		assert_eq!(resp["error"]["code"], "bad_request", "{label}");
	}

	// valid plist but the top level is not a Backup dictionary: the shape mismatch also 400s
	let mut buf = Vec::new();
	plist::Value::Array(vec![plist::Value::from(1)])
		.to_writer_binary(&mut buf)
		.expect("write plist");
	let (status, _, bytes) = request_bytes(
		&app.app,
		"POST",
		"/api/v1/backups/import/aidoku",
		buf,
		"application/octet-stream",
	)
	.await;
	assert_eq!(status, StatusCode::BAD_REQUEST);
	let resp: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
	assert_eq!(resp["error"]["code"], "bad_request");

	assert_eq!(db_dump(&app.db_path).await, before);
}

/// The tracker half of the import: Aidoku's entry ids become the bindings' track ids, tracker ids are mapped onto
/// this server's providers, and the track mode comes from the per-manga chapter display mode in the settings dump
#[tokio::test]
async fn import_aidoku_restores_tracker_bindings() {
	let app = test_app().await;
	scan(&app.app).await;
	let manga_id = register_example_manga(&app.app).await;

	let (status, body) = post_aib(&app.app, "").await;
	assert_eq!(status, StatusCode::OK, "import failed: {body}");
	assert_eq!(body["imported"]["trackers"], 2);

	let links = tracker_links(&app.app, manga_id).await;
	assert_eq!(links.len(), 1, "links: {links:?}");
	assert_eq!(links[0]["provider"], "anilist");
	assert_eq!(links[0]["trackId"], "101");
	assert_eq!(links[0]["title"], "Example Manga");
	// chapter display mode 1 = chapter: the manga was tracked chapter-by-chapter in Aidoku, and stays so here
	assert_eq!(links[0]["trackMode"], "chapter");
	assert_eq!(links[0]["chapterOffset"], 0);

	// myanimelist is this server's "mal"; the volume display mode (2) and the backup's offset survive the import
	let manga2_id = library_entry(&app.app, "Second Manga").await["id"]
		.as_i64()
		.expect("manga 2 id");
	let links = tracker_links(&app.app, manga2_id).await;
	assert_eq!(links.len(), 1, "links: {links:?}");
	assert_eq!(links[0]["provider"], "mal");
	assert_eq!(links[0]["trackId"], "202");
	assert_eq!(links[0]["title"], "Second Manga");
	assert_eq!(links[0]["trackMode"], "volume");
	assert_eq!(links[0]["chapterOffset"], 1);
}

/// The import is additive: a binding made in this app wins over the backup's for the same manga and provider
#[tokio::test]
async fn import_aidoku_keeps_an_existing_tracker_binding() {
	let app = test_app().await;
	scan(&app.app).await;
	let manga_id = register_example_manga(&app.app).await;
	let (status, _) = request(
		&app.app,
		"PUT",
		&format!("/api/v1/trackers/links/{manga_id}"),
		Some(json!({
			"provider": "anilist",
			"trackId": "local-1",
			"title": "Local",
			"trackMode": "volume",
			"chapterOffset": 3
		})),
	)
	.await;
	assert_eq!(status, StatusCode::OK);
	let before = tracker_links(&app.app, manga_id).await;

	let (status, body) = post_aib(&app.app, "").await;
	assert_eq!(status, StatusCode::OK, "import failed: {body}");
	assert_eq!(body["imported"]["trackers"], 2);
	assert_eq!(tracker_links(&app.app, manga_id).await, before);

	// the other binding the backup carries is still created on its own manga
	let manga2_id = library_entry(&app.app, "Second Manga").await["id"]
		.as_i64()
		.expect("manga 2 id");
	assert_eq!(
		tracker_links(&app.app, manga2_id)
			.await
			.iter()
			.map(|l| l["provider"].as_str().unwrap())
			.collect::<Vec<_>>(),
		["mal"]
	);
}

#[tokio::test]
async fn import_aidoku_preserves_missing_sources_without_installing_packages() {
	let app = test_app().await;
	scan(&app.app).await;
	let before = db_dump(&app.db_path).await;
	let (status, preview) = post_aib(&app.app, "?dryRun=true&preserveMissingSources=true").await;
	assert_eq!(status, StatusCode::OK, "{preview}");
	assert_eq!(preview["imported"]["library"], 3);
	assert_eq!(preview["imported"]["progress"], 4);
	assert_eq!(preview["imported"]["trackers"], 3);
	assert_eq!(preview["missingSources"], json!(["en.ghost-source"]));
	assert_eq!(preview["skipped"].as_array().unwrap().len(), 0);
	assert_eq!(preview["archivedTrackers"], 1);
	assert_eq!(db_dump(&app.db_path).await, before);

	let (status, committed) = post_aib(&app.app, "?preserveMissingSources=true").await;
	assert_eq!(status, StatusCode::OK, "{committed}");
	for field in ["imported", "included", "categoryNames", "missingSources", "archivedTrackers", "skipped"] {
		assert_eq!(committed[field], preview[field], "{field} differs from preview");
	}
	let pool = connect_db(&app.db_path).await;
	let (source_id, enabled, wasm_path): (i64, bool, String) =
		sqlx::query_as("SELECT id, enabled, wasm_path FROM source WHERE key = 'en.ghost-source'")
			.fetch_one(&pool).await.unwrap();
	assert!(!enabled);
	assert!(wasm_path.is_empty());
	let manga_id: i64 = sqlx::query_scalar("SELECT id FROM manga WHERE source_id = ? AND key = 'ghost-1'")
		.bind(source_id).fetch_one(&pool).await.unwrap();
	let (in_library,): (bool,) = sqlx::query_as("SELECT in_library FROM manga_user WHERE manga_id = ? AND user_id = 1")
		.bind(manga_id).fetch_one(&pool).await.unwrap();
	assert!(in_library);
	let progress: i64 = sqlx::query_scalar("SELECT cu.last_page_read FROM chapter_user cu JOIN chapter c ON c.id = cu.chapter_id WHERE c.manga_id = ? AND c.key = '9' AND cu.user_id = 1")
		.bind(manga_id).fetch_one(&pool).await.unwrap();
	assert_eq!(progress, 1);
	let tracker: String = sqlx::query_scalar("SELECT track_id FROM tracker_link WHERE manga_id = ? AND user_id = 1")
		.bind(manga_id).fetch_one(&pool).await.unwrap();
	assert_eq!(tracker, "404");
	pool.close().await;
	let (_, sources) = request(&app.app, "GET", "/api/v1/sources", None).await;
	assert!(!sources.as_array().unwrap().iter().any(|source| source["key"] == "en.ghost-source"));
	let after = db_dump(&app.db_path).await;
	let (status, _) = post_aib(&app.app, "?preserveMissingSources=true").await;
	assert_eq!(status, StatusCode::OK);
	assert_eq!(db_dump(&app.db_path).await, after);
	let chapter = chapter_by_key(&app.app, manga_id, "9").await;
	let (status, queued) = request(&app.app, "POST", "/api/v1/downloads", Some(json!({"chapterIds": [chapter["id"].as_i64().unwrap()]}))).await;
	assert_eq!(status, StatusCode::OK, "{queued}");
	assert_eq!(queued["queued"], json!([]));
}

#[tokio::test]
async fn unsupported_aidoku_bindings_are_inactive_and_survive_portable_backup() {
	let app = test_app().await;
	scan(&app.app).await;
	let before = db_dump(&app.db_path).await;
	let (status, preview) = post_aib(&app.app, "?dryRun=true&preserveMissingSources=true").await;
	assert_eq!(status, StatusCode::OK, "{preview}");
	assert_eq!(preview["archivedTrackers"], 1);
	assert_eq!(db_dump(&app.db_path).await, before);
	let (status, committed) = post_aib(&app.app, "?preserveMissingSources=true").await;
	assert_eq!(status, StatusCode::OK, "{committed}");
	assert_eq!(committed["archivedTrackers"], 1);
	let archive_key = "aidoku.inactive_tracker_bindings.v1";
	let (status, backup) = request(&app.app, "GET", "/api/v1/backups/document", None).await;
	assert_eq!(status, StatusCode::OK);
	let entries = backup["settings"][archive_key].as_array().unwrap();
	assert_eq!(entries.len(), 1);
	assert_eq!(entries[0]["trackerId"], "shikimori");
	assert_eq!(entries[0]["trackId"], "303");
	assert_eq!(entries[0]["sourceKey"], "en.example-source");
	let manga = library_entry(&app.app, "Aib Title One").await;
	assert!(!tracker_links(&app.app, manga["id"].as_i64().unwrap()).await.iter().any(|row| row["provider"] == "shikimori"));
	let (_, settings) = request(&app.app, "GET", "/api/v1/settings", None).await;
	assert!(settings.get(archive_key).is_none());
	let (status, _) = request(&app.app, "PUT", "/api/v1/settings", Some(json!({(archive_key): []}))).await;
	assert_eq!(status, StatusCode::OK);
	let (_, after_settings) = request(&app.app, "GET", "/api/v1/backups/document", None).await;
	assert_eq!(after_settings["settings"][archive_key], backup["settings"][archive_key]);

	let target = test_app().await;
	for _ in 0..2 {
		let (status, result) = request(&target.app, "POST", "/api/v1/backups/document?sections=settings", Some(backup.clone())).await;
		assert_eq!(status, StatusCode::OK, "{result}");
	}
	let (_, restored) = request(&target.app, "GET", "/api/v1/backups/document", None).await;
	assert_eq!(restored["settings"][archive_key], backup["settings"][archive_key]);
}

#[tokio::test]
async fn portable_restore_preserves_offline_manga_progress_and_tracker_associations() {
	let app = test_app().await;
	scan(&app.app).await;
	let (status, _) = post_aib(&app.app, "?preserveMissingSources=true").await;
	assert_eq!(status, StatusCode::OK);
	let (status, backup) = request(&app.app, "GET", "/api/v1/backups/document", None).await;
	assert_eq!(status, StatusCode::OK);
	assert_eq!(backup["trackerBindings"].as_array().unwrap().len(), 3);
	assert!(backup["sources"].as_array().unwrap().iter().any(|source| source["key"] == "en.ghost-source" && source["retainOffline"] == true));
	let target = test_app().await;
	scan(&target.app).await;
	for _ in 0..2 {
		let (status, restored) = request(&target.app, "POST", "/api/v1/backups/document", Some(backup.clone())).await;
		assert_eq!(status, StatusCode::OK, "{restored}");
		assert_eq!(restored["restored"]["trackerBindings"], 3);
	}
	let (_, exported) = request(&target.app, "GET", "/api/v1/backups/document", None).await;
	for field in ["trackerBindings", "progress", "categories"] {
		assert_eq!(exported[field], backup[field], "{field} did not survive backup");
	}
	let pool = connect_db(&target.db_path).await;
	let (enabled, path, in_library, progress, track_id): (bool, String, bool, i64, String) = sqlx::query_as(
		"SELECT s.enabled, s.wasm_path, mu.in_library, cu.last_page_read, tl.track_id
		 FROM source s JOIN manga m ON m.source_id=s.id
		 JOIN manga_user mu ON mu.manga_id=m.id AND mu.user_id=1
		 JOIN chapter c ON c.manga_id=m.id JOIN chapter_user cu ON cu.chapter_id=c.id AND cu.user_id=1
		 JOIN tracker_link tl ON tl.manga_id=m.id AND tl.user_id=1
		 WHERE s.key='en.ghost-source' AND m.key='ghost-1' AND c.key='9'",
	).fetch_one(&pool).await.unwrap();
	assert_eq!((enabled, path, in_library, progress, track_id), (false, String::new(), true, 1, "404".into()));
	assert_eq!(exported["settings"]["aidoku.inactive_tracker_bindings.v1"], backup["settings"]["aidoku.inactive_tracker_bindings.v1"]);
	assert_eq!(request(&target.app, "GET", "/api/v1/downloads", None).await.1, json!([]));
}

#[tokio::test]
async fn aidoku_commit_refuses_a_stale_source_preview_without_writing() {
	let app = test_app().await;
	scan(&app.app).await;

	let (status, preview) = post_aib(&app.app, "?dryRun=true").await;
	assert_eq!(status, StatusCode::OK, "{preview}");
	let fingerprint = preview["previewFingerprint"].as_str().expect("preview fingerprint");
	assert_eq!(fingerprint.len(), 43);

	let pool = connect_db(&app.db_path).await;
	sqlx::query("UPDATE source SET enabled = 0 WHERE key = 'en.example-source'")
		.execute(&pool).await.unwrap();
	let before = db_dump(&app.db_path).await;

	let (status, result) = post_aib(&app.app, &format!("?previewFingerprint={fingerprint}")).await;
	assert_eq!(status, StatusCode::CONFLICT, "{result}");
	assert_eq!(result["error"]["code"].as_str().or_else(|| result["code"].as_str()), Some("aidoku_preview_changed"));
	assert_eq!(db_dump(&app.db_path).await, before);

	let (status, updated) = post_aib(&app.app, "?dryRun=true").await;
	assert_eq!(status, StatusCode::OK);
	let new_fingerprint = updated["previewFingerprint"].as_str().unwrap();
	assert_ne!(new_fingerprint, fingerprint);
	let (status, result) = post_aib(&app.app, &format!("?previewFingerprint={new_fingerprint}")).await;
	assert_eq!(status, StatusCode::OK, "{result}");
}

#[tokio::test]
async fn aidoku_review_protects_unread_and_applies_only_selected_rewinds() {
	let app = test_app().await;
	scan(&app.app).await;
	let manga_id = register_example_manga(&app.app).await;
	assert_eq!(post_aib(&app.app, "").await.0, StatusCode::OK);
	let ch3 = chapter_by_key(&app.app, manga_id, "3").await["id"].as_i64().unwrap();
	let ch7 = chapter_by_key(&app.app, manga_id, "7").await["id"].as_i64().unwrap();
	let edit = |id, body| {
		let router = app.app.clone();
		async move { request(&router, "PATCH", &format!("/api/v1/chapter/{id}"), Some(body)).await }
	};

	assert_eq!(edit(ch7, json!({"isRead":false})).await.0, StatusCode::OK);
	assert_eq!(edit(ch3, json!({"lastPageRead":9,"isBookmarked":true})).await.0, StatusCode::OK);
	let (status, preview) = post_aib(&app.app, "?dryRun=true&reviewProgress=true").await;
	assert_eq!(status, StatusCode::OK);
	let differences = preview["progressDifferences"].as_array().expect("progress comparison");
	assert!(differences.iter().any(|d| d["chapterId"] == ch3 && d["currentPage"] == 9 && d["backupPage"] == 5));
	assert!(differences.iter().any(|d| d["chapterId"] == ch7 && d["currentRead"] == false && d["protected"] == true));

	let fingerprint = preview["previewFingerprint"].as_str().unwrap();
	assert_eq!(edit(ch3, json!({"lastPageRead":10})).await.0, StatusCode::OK);
	let stale = format!("?reviewProgress=true&previewFingerprint={fingerprint}&progressCorrections={ch3}");
	assert_eq!(post_aib(&app.app, &stale).await.0, StatusCode::CONFLICT);
	assert_eq!(chapter_by_key(&app.app, manga_id, "3").await["lastPageRead"], 10);

	let (_, fresh) = post_aib(&app.app, "?dryRun=true&reviewProgress=true").await;
	let fingerprint = fresh["previewFingerprint"].as_str().unwrap();
	let confirm = format!("?reviewProgress=true&previewFingerprint={fingerprint}&progressCorrections={ch3}");
	let (status, result) = post_aib(&app.app, &confirm).await;
	assert_eq!(status, StatusCode::OK, "{result}");
	assert_eq!(result["correctedProgress"], 1);
	let corrected = chapter_by_key(&app.app, manga_id, "3").await;
	assert_eq!(corrected["lastPageRead"], 5);
	assert_eq!(corrected["isBookmarked"], true);
	assert_eq!(chapter_by_key(&app.app, manga_id, "7").await["isRead"], false);
	assert_eq!(post_aib(&app.app, "").await.0, StatusCode::OK);
	assert_eq!(chapter_by_key(&app.app, manga_id, "7").await["isRead"], false);
	let mut old: plist::Value = plist::from_bytes(AIB).unwrap();
	let history = old.as_dictionary_mut().unwrap().get_mut("history").unwrap().as_array_mut().unwrap();
	history[0].as_dictionary_mut().unwrap().insert("progress".into(), plist::Value::from(9));
	let mut bytes = Vec::new();
	old.to_writer_binary(&mut bytes).unwrap();
	assert_eq!(post_aib_bytes(&app.app, "", bytes).await.0, StatusCode::OK);
	assert_eq!(chapter_by_key(&app.app, manga_id, "3").await["lastPageRead"], 5);
}

#[tokio::test]
async fn aidoku_review_rejects_unreviewed_or_incomplete_corrections_without_writes() {
	let app = test_app().await;
	scan(&app.app).await;
	let manga_id = register_example_manga(&app.app).await;
	assert_eq!(post_aib(&app.app, "").await.0, StatusCode::OK);
	let chapter = chapter_by_key(&app.app, manga_id, "3").await["id"].as_i64().unwrap();
	let mut backup: plist::Value = plist::from_bytes(AIB).unwrap();
	let row = backup.as_dictionary_mut().unwrap().get_mut("history").unwrap().as_array_mut().unwrap()[0].as_dictionary_mut().unwrap();
	row.insert("progress".into(), plist::Value::from(1));
	row.remove("completed");
	let mut bytes = Vec::new();
	backup.to_writer_binary(&mut bytes).unwrap();
	let before = db_dump(&app.db_path).await;
	let (status, preview) = post_aib_bytes(&app.app, "?dryRun=true&reviewProgress=true", bytes.clone()).await;
	assert_eq!(status, StatusCode::OK, "{preview}");
	let difference = &preview["progressDifferences"][0];
	assert_eq!(difference["chapterId"], chapter);
	assert_eq!(difference["canCorrect"], false);
	assert_eq!(difference["backupRead"], Value::Null);
	let fingerprint = preview["previewFingerprint"].as_str().unwrap();
	for query in [
		format!("?reviewProgress=true&previewFingerprint={fingerprint}&progressCorrections={chapter}"),
		format!("?reviewProgress=true&previewFingerprint={fingerprint}&progressCorrections=99999"),
		format!("?reviewProgress=true&progressCorrections={chapter}"),
	] {
		assert_eq!(post_aib_bytes(&app.app, &query, bytes.clone()).await.0, StatusCode::BAD_REQUEST);
	}
	assert_eq!(db_dump(&app.db_path).await, before);
}

#[tokio::test]
async fn aidoku_export_preview_requires_a_fresh_complete_target_backup() {
	let app = test_app().await;
	let mut payload = plist::Dictionary::new();
	payload.insert("date".into(), plist::Value::Date(std::time::SystemTime::now().into()));
	payload.insert("history".into(), plist::Value::Array(Vec::new()));
	payload.insert("chapters".into(), plist::Value::Array(Vec::new()));
	payload.insert("readingSessions".into(), plist::Value::Array(Vec::new()));
	// A missing updates section cannot preserve chapter-linked updates during restore.
	let mut bytes = Vec::new();
	plist::Value::Dictionary(payload).to_writer_binary(&mut bytes).unwrap();
	let before = db_dump(&app.db_path).await;
	let (status, _, _) = request_bytes(
		&app.app,
		"POST",
		"/api/v1/backups/export/aidoku?completeBackup=true",
		bytes,
		"application/octet-stream",
	).await;
	assert_eq!(status, StatusCode::BAD_REQUEST);
	assert_eq!(db_dump(&app.db_path).await, before);
}

fn aidoku_export_target() -> Vec<u8> {
	let mut target: plist::Value = plist::from_bytes(AIB).unwrap();
	let target = target.as_dictionary_mut().unwrap();
	let now: plist::Date = std::time::SystemTime::now().into();
	target.insert("date".into(), plist::Value::Date(now));
	for section in ["chapters", "history"] {
		target.get_mut(section).unwrap().as_array_mut().unwrap().retain(|row| {
			row.as_dictionary().unwrap()["sourceId"].as_string() == Some("en.example-source")
		});
	}
	// Aidoku emits zero when the chapter's page count is unknown.
	target.get_mut("history").unwrap().as_array_mut().unwrap()[0]
		.as_dictionary_mut().unwrap().insert("total".into(), plist::Value::from(0));
	let mut session = plist::Dictionary::new();
	for (name, value) in [("sourceId", "en.example-source"), ("mangaId", "1"), ("chapterId", "3")] {
		session.insert(name.into(), plist::Value::from(value));
	}
	let mut update = session.clone();
	update.insert("date".into(), plist::Value::Date(now));
	update.insert("viewed".into(), plist::Value::Boolean(true));
	target.insert("updates".into(), plist::Value::Array(vec![plist::Value::Dictionary(update)]));
	session.insert("startDate".into(), plist::Value::Date((std::time::SystemTime::now() - std::time::Duration::from_secs(60)).into()));
	session.insert("endDate".into(), plist::Value::Date(now));
	session.insert("pagesRead".into(), plist::Value::from(4));
	target.insert("readingSessions".into(), plist::Value::Array(vec![plist::Value::Dictionary(session)]));
	let mut bytes = Vec::new();
	plist::Value::Dictionary(target.clone()).to_writer_binary(&mut bytes).unwrap();
	bytes
}

#[tokio::test]
async fn aidoku_export_keeps_sessions_and_updates_and_blocks_stale_or_orphaned_restore() {
	const PATH: &str = "/api/v1/backups/export/aidoku?completeBackup=true";
	let app = test_app().await;
	scan(&app.app).await;
	let manga_id = register_example_manga(&app.app).await;
	assert_eq!(post_aib(&app.app, "").await.0, StatusCode::OK);
	let ch3 = chapter_by_key(&app.app, manga_id, "3").await["id"].as_i64().unwrap();
	let bytes = aidoku_export_target();
	let before = db_dump(&app.db_path).await;
	let (status, headers, preview) = request_bytes(&app.app, "POST", PATH, bytes.clone(), "application/octet-stream").await;
	assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&preview));
	assert_eq!(headers["cache-control"], "no-store");
	let preview: Value = serde_json::from_slice(&preview).unwrap();
	assert_eq!(preview["readingSessions"], 1);
	assert_eq!(preview["updates"], 1);
	assert_eq!(preview["removedHistory"], 0);
	assert_eq!(preview["history"], 3);
	let fingerprint = preview["previewFingerprint"].as_str().unwrap();
	let download = format!("{PATH}&previewFingerprint={fingerprint}");
	let (status, _, output) = request_bytes(&app.app, "POST", &download, bytes.clone(), "application/octet-stream").await;
	if preview["fixtureDownloadEnabled"] == true {
		assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&output));
		assert!(output.starts_with(b"bplist00"));
		let original: plist::Value = plist::from_bytes(&bytes).unwrap();
		let restored: plist::Value = plist::from_bytes(&output).unwrap();
		let restored = restored.as_dictionary().unwrap();
		let original = original.as_dictionary().unwrap();
		assert_eq!(restored["readingSessions"], original["readingSessions"]);
		assert_eq!(restored["updates"], original["updates"]);
		for section in ["library", "categories", "trackItems", "settings", "sources", "sourceLists"] {
			assert!(!restored.contains_key(section));
		}
	} else {
		assert_eq!(status, StatusCode::NOT_IMPLEMENTED);
	}
	assert_eq!(db_dump(&app.db_path).await, before);

	let mut newer: plist::Value = plist::from_bytes(&bytes).unwrap();
	newer.as_dictionary_mut().unwrap().get_mut("history").unwrap().as_array_mut().unwrap()[0]
		.as_dictionary_mut().unwrap().insert("dateRead".into(), plist::Value::Date(std::time::SystemTime::now().into()));
	let mut newer_bytes = Vec::new();
	newer.to_writer_binary(&mut newer_bytes).unwrap();
	let (status, _, error) = request_bytes(&app.app, "POST", PATH, newer_bytes, "application/octet-stream").await;
	assert_eq!(status, StatusCode::BAD_REQUEST);
	assert!(String::from_utf8_lossy(&error).contains("Aidoku has newer reading history"));
	assert_eq!(db_dump(&app.db_path).await, before);

	let route = format!("/api/v1/chapter/{ch3}");
	assert_eq!(request(&app.app, "PATCH", &route, Some(json!({"lastPageRead":1}))).await.0, StatusCode::OK);
	if preview["fixtureDownloadEnabled"] == true {
		assert_eq!(request_bytes(&app.app, "POST", &download, bytes.clone(), "application/octet-stream").await.0, StatusCode::CONFLICT);
	}
	assert_eq!(request(&app.app, "PATCH", &route, Some(json!({"isRead":false}))).await.0, StatusCode::OK);
	assert_eq!(request_bytes(&app.app, "POST", PATH, bytes, "application/octet-stream").await.0, StatusCode::BAD_REQUEST);
}
